    /// <summary>
    /// Update the @exttimestamp field with the extended timestamp of @timestamp
    /// For the first call of the method, @exttimestamp should point to a location
    /// with a value of -1.
    /// </summary>
    /// <remarks>
    /// <para>
    /// This function is able to handle both forward and backward timestamps taking
    /// into account:
    ///   - timestamp wraparound making sure that the returned value is properly increased.
    ///   - timestamp unwraparound making sure that the returned value is properly decreased.
    /// </para>
    /// </remarks>
    /// <param name="exttimestamp">The <c>exttimestamp</c> argument.</param>
    /// <param name="timestamp">The <c>timestamp</c> argument.</param>
    /// <returns>The extended timestamp of @timestamp or 0 if the result can't go anywhere backwards.</returns>
    public static ulong ExtTimestamp(ref ulong exttimestamp, uint timestamp)
    {
        ulong exttimestampNative = exttimestamp;
        ulong nativeResult = GstRtpBufferExtTimestamp(&exttimestampNative, timestamp);
        exttimestamp = exttimestampNative;
        return nativeResult;
    }

    /// <summary>Map the contents of @buffer into @rtp.</summary>
    /// <param name="buffer">The <c>buffer</c> argument.</param>
    /// <param name="flags">The <c>flags</c> argument.</param>
    /// <param name="rtp">The <c>rtp</c> argument.</param>
    /// <returns>%TRUE if @buffer could be mapped.</returns>
    public static bool MapBuffer(Gst.Buffer buffer, Gst.MapFlags flags, out Gst.Rtp.RTPBuffer rtp)
    {
        ArgumentNullException.ThrowIfNull(buffer);
        Gst.Rtp.RTPBuffer rtpNative = default;
        int nativeResult = GstRtpBufferMap(buffer.Handle, (int)flags, &rtpNative);
        System.GC.KeepAlive(buffer);
        rtp = rtpNative;
        return nativeResult != 0;
    }

    /// <summary>
    /// Allocate a new #GstBuffer with enough data to hold an RTP packet with
    /// @csrc_count CSRCs, a payload length of @payload_len and padding of @pad_len.
    /// All other RTP header fields will be set to 0/FALSE.
    /// </summary>
    /// <param name="payloadLen">The <c>payloadLen</c> argument.</param>
    /// <param name="padLen">The <c>padLen</c> argument.</param>
    /// <param name="csrcCount">The <c>csrcCount</c> argument.</param>
    /// <returns>
    /// A newly allocated buffer that can hold an RTP packet with given
    /// parameters.
    /// </returns>
    public static Gst.Buffer NewAllocate(uint payloadLen, byte padLen, byte csrcCount)
    {
        nint nativeResult = GstRtpBufferNewAllocate(payloadLen, padLen, csrcCount);
        return Gst.Buffer.FromNative(nativeResult, Gst.Interop.Transfer.Full)
            ?? throw new InvalidOperationException("gst_rtp_buffer_new_allocate returned no value.");
    }

    /// <summary>
    /// Create a new #GstBuffer that can hold an RTP packet that is exactly
    /// @packet_len long. The length of the payload depends on @pad_len and
    /// @csrc_count and can be calculated with gst_rtp_buffer_calc_payload_len().
    /// All RTP header fields will be set to 0/FALSE.
    /// </summary>
    /// <param name="packetLen">The <c>packetLen</c> argument.</param>
    /// <param name="padLen">The <c>padLen</c> argument.</param>
    /// <param name="csrcCount">The <c>csrcCount</c> argument.</param>
    /// <returns>A newly allocated buffer that can hold an RTP packet of @packet_len.</returns>
    public static Gst.Buffer NewAllocateLen(uint packetLen, byte padLen, byte csrcCount)
    {
        nint nativeResult = GstRtpBufferNewAllocateLen(packetLen, padLen, csrcCount);
        return Gst.Buffer.FromNative(nativeResult, Gst.Interop.Transfer.Full)
            ?? throw new InvalidOperationException("gst_rtp_buffer_new_allocate_len returned no value.");
    }

    /// <summary>
    /// Create a new buffer and set the data to a copy of @len
    /// bytes of @data and the size to @len. The data will be freed when the buffer
    /// is freed.
    /// </summary>
    /// <param name="data">
    /// data for the new
    ///   buffer
    /// </param>
    /// <returns>A newly allocated buffer with a copy of @data and of size @len.</returns>
    public static Gst.Buffer NewCopyData(System.ReadOnlySpan<byte> data)
    {
        fixed (byte* dataPointer = data)
        {
            nint nativeResult = GstRtpBufferNewCopyData(dataPointer, (nuint)data.Length);
            return Gst.Buffer.FromNative(nativeResult, Gst.Interop.Transfer.Full)
                ?? throw new InvalidOperationException("gst_rtp_buffer_new_copy_data returned no value.");
        }
    }

